import{z as A,x as B,o as r,c as d,q as s,j as i,D as e,d as t,s as o,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"VPN 对零信任","description":"","frontmatter":{"title":"VPN 对零信任","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vpn-zero-trust.md","filePath":"cs/vpn-zero-trust.md","lastUpdated":1791063341000}'),p={name:"cs/vpn-zero-trust.md"};function D(m,a,P,u,h,c){const n=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=s('<h1 id="vpn-对零信任" tabindex="-1">VPN 对零信任 <a class="header-anchor" href="#vpn-对零信任" aria-label="Permalink to &quot;VPN 对零信任&quot;">​</a></h1><div class="epigraph"><p>VPN 把远程主机变成「已在内网」；零信任把每次请求当成来自敌意网络。二者不是口号替换，是信任锚从网段迁到身份、设备与请求上下文。</p><footer>—— 据 Kindervag 的零信任陈述；NIST SP 800-207；对照 Anderson 对边界模型</footer></div><p>上一课<a href="/cs/wireguard">WireGuard</a>仍是一条（漂亮的）隧道。缺口是<strong>边界模型本身</strong>：进了隧道就侧向移动。本课对照，不把零信任架构的整本 SP 提前写完（那在治理课序）。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IPsec/WG 成功后，用户拥有网段级路由。横向用<a href="/cs/arp-spoofing">ARP</a>或扫描内网服务。零信任：认证+设备姿态+最小授权到应用，网络层加密仍可有，但不等于授权。缺口是信任迁移，不是再配一条隧道。</p><h3 id="加密不等于授权" tabindex="-1">加密不等于授权 <a class="header-anchor" href="#加密不等于授权" aria-label="Permalink to &quot;加密不等于授权&quot;">​</a></h3><p>mTLS 与隧道都加密。授权是「这个主体对这个资源的这个动作」。</p><p><span class="marginnote">「零信任」翻译成大白话：不再问「你从哪个网段来」，而是对每次请求问三件事——你是谁、你的设备健康吗、这个动作被允许吗。网络位置从信任来源降级成不可信环境里的一个变量。</span></p><p><span class="marginnote">NIST SP 800-207。BeyondCorp 是公开工程叙述。本课不写打穿某企业 VPN 的步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列 VPN 假设：私网、粗粒度 ACL。列零信任假设：身份提供者、短命凭证、每请求验。指出混合：隧道仍用于合规或遗留协议，应用仍要鉴权。</p>',12)),(r(),i(l,null,{default:e(()=>[o(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20VPN%5B%22%E8%BF%9B%E9%9A%A7%E9%81%93%20%3D%20%E5%86%85%E7%BD%91%22%5D%20--%3E%20LAT%5B%22%E4%BE%A7%E5%90%91%E9%9D%A2%E5%A4%A7%22%5D%0A%20%20ZT%5B%22%E6%AF%8F%E8%AF%B7%E6%B1%82%E8%BA%AB%E4%BB%BD%E4%B8%8E%E5%A7%BF%E6%80%81%22%5D%20--%3E%20MIN%5B%22%E6%9C%80%E5%B0%8F%E6%8E%88%E6%9D%83%22%5D%0A%20%20TUN%5B%22%E4%BB%8D%E5%8F%AF%E5%8A%A0%E5%AF%86%E4%BC%A0%E8%BE%93%22%5D%20--%3E%20ZT%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"给「短命凭证」一个数字直觉：传统 VPN 证书可能一年有效，而零信任的访问令牌常只有几分钟寿命——即便被偷走，攻击窗口也只是你起身接一杯水的工夫。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"信道单元要结束「链路保密」并开始「谁在链上」。Wi-Fi 下一课是最后一跳的链路层合同，同样不能代替应用身份。",-1)),(r(),i(l,null,{default:e(()=>[o(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E5%BA%94%E7%94%A8%E8%AF%B7%E6%B1%82%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20ID%5B%22%E8%BA%AB%E4%BB%BD%E6%8F%90%E4%BE%9B%E8%80%85%E9%AA%8C%E8%AF%81%E4%BD%A0%E6%98%AF%E8%B0%81%22%5D%0A%20%20ID%20--%3E%20DEV%5B%22%E9%87%87%E9%9B%86%E8%AE%BE%E5%A4%87%E5%A7%BF%E6%80%81%E4%B8%8E%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20DEV%20--%3E%20POL%7B%22%E7%AD%96%E7%95%A5%E5%BC%95%E6%93%8E%3A%20%E6%BB%A1%E8%B6%B3%E6%9C%80%E5%B0%8F%E6%8E%88%E6%9D%83%E5%90%97%3F%22%7D%0A%20%20POL%20--%20%E6%98%AF%20--%3E%20GRANT%5B%22%E7%AD%BE%E5%8F%91%E7%9F%AD%E5%91%BD%E5%87%AD%E8%AF%81%2C%20%E6%94%BE%E8%A1%8C%E6%9C%AC%E6%AC%A1%E8%AF%B7%E6%B1%82%22%5D%0A%20%20POL%20--%20%E5%90%A6%20--%3E%20DENY%5B%22%E6%8B%92%E7%BB%9D%E5%B9%B6%E8%AE%B0%E5%BD%95%E5%AE%A1%E8%AE%A1%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">常见误区：以为上了零信任就不需要加密隧道。实际上两者各管一段——WireGuard/mTLS 管路径保密，零信任管每次请求的授权；合规场景里最常见的是二者叠加使用。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开策略引擎产品。WPA2/WPA3 下一课：无线链路的认证与前向。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>隧道解决路径保密与粗准入，不解决横向。</li><li>零信任把锚放到身份与请求。</li><li>二者可叠加：加密传输 + 每请求授权。</li><li>下一课 WPA2/WPA3。</li><li>出处：NIST SP 800-207；Kindervag；Anderson, <em>Security Engineering</em>。</li></ul>',5))])}const _=A(p,[["render",D]]);export{f as __pageData,_ as default};
